1: /* ==========================================================================
2:    THEATRON CINEMA LOUNGES — Coming Soon Interactive Controller
3:    ========================================================================== */
4: 
5: (function () {
6:   'use strict';
7: 
8:   // ------------------------------------------------------------------------
9:   // Curated Upcoming Premieres Dataset
10:   // ------------------------------------------------------------------------
11:   const PREMIERES = [
12:     {
13:       id: 'dynasty-of-glass',
14:       title: 'DYNASTY OF GLASS',
15:       genre: 'Drama',
16:       meta: 'English • 2h 35m • R',
17:       synopsis:
18:         'An architectural dynasty fractures over succession rights when their flagship Manhattan tower unveils an unprecedented private vault.',
19:       director: 'Eleanor Sterling',
20:       cast: 'Sebastian Cross, Genevieve Hart, Miles Sterling',
21:       releaseDate: 'Fri, Dec 18, 2026',
22:       remainingSeconds: 28 * 86400 + 14 * 3600 + 42,
23:       reminderActive: true,
24:       formatSpec: 'IMAX Dual-Laser 1.90:1 • Dolby Atmos',
25:       screeningNotes:
26:         'Opening night gala features a live architectural foreword and vintage Krug Brut reception in the Fifth Avenue Mezzanine Salon.',
27:       posterImage: 'posters/dynasty-glass.jpg',
28:     },
29:     {
30:       id: 'mirage-of-kings',
31:       title: 'MIRAGE OF KINGS',
32:       genre: 'Action',
33:       meta: 'Arabic • 2h 11m • PG-13',
34:       synopsis:
35:         'An antiquities investigator races across ancient caravan routes to protect an astrolabe capable of unlocking a sunken Nabataean treasury.',
36:       director: 'Tariq Al-Jamil',
37:       cast: 'Zayd Haddad, Layla Mansour, Omar Farooq',
38:       releaseDate: 'Fri, Jan 15, 2027',
39:       remainingSeconds: 52 * 86400 + 14 * 3600 + 19,
40:       reminderActive: false,
41:       formatSpec: '70mm Large Format • 128-Channel Atmos',
42:       screeningNotes:
43:         'Shot on 65mm large-format stock across Petra and Wadi Rum; paired with food and drink selections for VIP Gold members.',
44:       posterImage: 'posters/mirage-kings.jpg',
45:     },
46:     {
47:       id: 'nocturne-in-vienna',
48:       title: 'NOCTURNE IN VIENNA',
49:       genre: 'Thriller',
50:       meta: 'German • 2h 18m • R',
51:       synopsis:
52:         'During a snowbound winter festival at the Musikverein, a celebrated conductor discovers a hidden cipher woven into an unperformed Mahler manuscript.',
53:       director: 'Lukas Von Berg',
54:       cast: 'Clara Lindholm, Anton Weber, Sofia Moretti',
55:       releaseDate: 'Fri, Feb 12, 2027',
56:       remainingSeconds: 78 * 86400 + 19 * 3600 + 55,
57:       reminderActive: true,
58:       formatSpec: '4K Dual-Laser • Custom Acoustic Suite Profile',
59:       screeningNotes:
60:         'Mastered specifically for THEATRON’s 0.28s RT60 maroon velvet auditoriums to preserve whispered string harmonics and hall resonance.',
61:       posterImage: 'posters/nocturne-obsidian.jpg',
62:     },
63:     {
64:       id: 'the-obsidian-meridian',
65:       title: 'THE OBSIDIAN MERIDIAN',
66:       genre: 'Sci-Fi',
67:       meta: 'English • 2h 44m • PG-13',
68:       synopsis:
69:         'Aboard an orbital observatory stationed above the solar terminator, an astrophysicist intercepts a recurring geometric signal predating human civilization.',
70:       director: 'Julian Mercer',
71:       cast: 'Elena Vance, Idris Thorne, Kenji Sato',
72:       releaseDate: 'Fri, Mar 19, 2027',
73:       remainingSeconds: 113 * 86400 + 20 * 3600 + 8,
74:       reminderActive: false,
75:       formatSpec: 'IMAX Dual-Laser 1.43:1 • Sub-Bass Tactile Array',
76:       screeningNotes:
77:         'Includes 42 minutes of expanded 1.43:1 orbital sequences calibrated at 22 foot-lamberts for pure obsidian-black space contrast.',
78:       posterImage: 'posters/ninth-monolith.jpg',
79:     },
80:   ];
81: 
82:   // ------------------------------------------------------------------------
83:   // State
84:   // ------------------------------------------------------------------------
85:   let activeFilter = 'All Premieres';
86:   let searchQuery = '';
87: 
88:   // ------------------------------------------------------------------------
89:   // Utilities & Toast
90:   // ------------------------------------------------------------------------
91:   function escapeHtml(str) {
92:     return String(str)
93:       .replace(/&/g, '&amp;')
94:       .replace(/</g, '&lt;')
95:       .replace(/>/g, '&gt;')
96:       .replace(/"/g, '&quot;')
97:       .replace(/'/g, '&#39;');
98:   }
99: 
100:   function formatCountdownParts(totalSeconds) {
101:     const safe = Math.max(0, totalSeconds);
102:     const days = Math.floor(safe / 86400);
103:     const hours = Math.floor((safe % 86400) / 3600);
104:     const secs = safe % 60;
105:     return {
106:       days: String(days).padStart(2, '0'),
107:       hours: String(hours).padStart(2, '0'),
108:       secs: String(secs).padStart(2, '0'),
109:     };
110:   }
111: 
112:   function showToast(title, detail) {
113:     const region = document.getElementById('toastRegion');
114:     if (!region) return;
115: 
116:     const toast = document.createElement('div');
117:     toast.className =
118:       'toast-item pointer-events-auto flex items-start gap-3 rounded-2xl border border-[#D4AF6A]/45 bg-[#181516]/95 px-4 py-3.5 shadow-[0_14px_34px_rgba(0,0,0,0.6)] backdrop-blur-md';
119: 
120:     toast.innerHTML = `
121:       <span class="mt-0.5 flex h-6 w-6 shrink-0 items-center justify-center rounded-full border border-[#8A2B3B] bg-[#3D141B] text-[#D4AF6A]">
122:         <svg class="h-3.5 w-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
123:           <polyline points="20 6 9 17 4 12" />
124:         </svg>
125:       </span>
126:       <div class="min-w-0 flex-1">
127:         <p class="text-xs font-semibold uppercase tracking-[0.14em] text-[#F5F2EB]">${escapeHtml(title)}</p>
128:         ${detail ? `<p class="mt-0.5 text-xs text-[#9E9895]">${escapeHtml(detail)}</p>` : ''}
129:       </div>
130:     `;
131: 
132:     region.appendChild(toast);
133:     setTimeout(() => {
134:       toast.style.opacity = '0';
135:       toast.style.transform = 'translateY(6px)';
136:       toast.style.transition = 'opacity 0.2s ease, transform 0.2s ease';
137:       setTimeout(() => toast.remove(), 220);
138:     }, 3400);
139:   }
140: 
141:   // ------------------------------------------------------------------------
142:   // 1. Navigation & Mobile Drawer
143:   // ------------------------------------------------------------------------
144:   function initNavigation() {
145:     const mobileBtn = document.getElementById('mobileMenuBtn');
146:     const drawer = document.getElementById('mobileNavDrawer');
147:     const iconOpen = document.getElementById('mobileMenuIconOpen');
148:     const iconClose = document.getElementById('mobileMenuIconClose');
149: 
150:     if (mobileBtn && drawer) {
151:       mobileBtn.addEventListener('click', () => {
152:         const isHidden = drawer.classList.toggle('hidden');
153:         mobileBtn.setAttribute('aria-expanded', String(!isHidden));
154:         iconOpen.classList.toggle('hidden', !isHidden);
155:         iconClose.classList.toggle('hidden', isHidden);
156:       });
157:     }
158: 
159:     document.querySelectorAll('[data-nav]').forEach((link) => {
160:       link.addEventListener('click', (e) => {
161:         const target = link.getAttribute('data-nav');
162:         if (target === 'Coming Soon' || target === 'About Us' || target === 'Help & Contact') {
163:           return; // Allow real page navigation
164:         }
165:         e.preventDefault();
166:         showToast(`Navigating to ${target}`, 'Currently viewing Coming Soon — Early Ticket Alerts.');
167:       });
168:     });
169:   }
170: 
171:   // ------------------------------------------------------------------------
172:   // 2. Live Reminder Counter & Filter Controls
173:   // ------------------------------------------------------------------------
174:   function updateReminderCounter() {
175:     const count = PREMIERES.filter((p) => p.reminderActive).length;
176:     const label = document.getElementById('reminderCountLabel');
177:     const pill = document.getElementById('reminderStatusPill');
178: 
179:     if (label) {
180:       label.textContent = `${count} Active Reminder(s)`;
181:     }
182:     if (pill) {
183:       pill.classList.toggle('status-pill-active', activeFilter === 'Active Reminders Only');
184:     }
185:   }
186: 
187:   function syncFilterPillsUi() {
188:     document.querySelectorAll('#genreFilterPills .filter-pill').forEach((btn) => {
189:       const isMatch = btn.getAttribute('data-filter') === activeFilter;
190:       btn.classList.toggle('filter-pill-active', isMatch);
191:       btn.setAttribute('aria-selected', String(isMatch));
192:     });
193:     updateReminderCounter();
194:   }
195: 
196:   function getFilteredPremieres() {
197:     return PREMIERES.filter((film) => {
198:       if (activeFilter === 'Drama' && film.genre !== 'Drama') return false;
199:       if (activeFilter === 'Action' && film.genre !== 'Action') return false;
200:       if (activeFilter === 'Sci-Fi / Thriller' && film.genre !== 'Sci-Fi' && film.genre !== 'Thriller') {
201:         return false;
202:       }
203:       if (activeFilter === 'Active Reminders Only' && !film.reminderActive) return false;
204: 
205:       if (searchQuery.trim()) {
206:         const q = searchQuery.trim().toLowerCase();
207:         const haystack = `${film.title} ${film.director} ${film.cast} ${film.genre}`.toLowerCase();
208:         if (!haystack.includes(q)) return false;
209:       }
210:       return true;
211:     });
212:   }
213: 
214:   // ------------------------------------------------------------------------
215:   // 3. Render Horizontal Premiere Cards Stack
216:   // ------------------------------------------------------------------------
217:   function renderPremieres() {
218:     const stack = document.getElementById('premieresStack');
219:     if (!stack) return;
220: 
221:     const list = getFilteredPremieres();
222: 
223:     if (list.length === 0) {
224:       stack.innerHTML = `
225:         <div class="luxury-card p-10 text-center">
226:           <p class="eyebrow">EARLY TICKET ALERTS</p>
227:           <h2 class="mt-2 font-serif text-xl uppercase tracking-[0.14em] text-[#F5F2EB]">
228:             NO PREMIERES MATCH YOUR FILTER
229:           </h2>
230:           <p class="mt-2 text-sm text-[#9E9895]">
231:             Clear your search query or switch back to All Premieres to inspect the complete 2026–2027 gala calendar.
232:           </p>
233:           <button
234:             id="clearFiltersBtn"
235:             type="button"
236:             class="mt-5 inline-flex items-center justify-center rounded-xl bg-[#D4AF6A] px-5 py-2.5 text-xs font-semibold uppercase tracking-[0.14em] text-[#121011] transition hover:bg-[#e2c282]"
237:           >
238:             Show All Premieres
239:           </button>
240:         </div>
241:       `;
242:       document.getElementById('clearFiltersBtn')?.addEventListener('click', () => {
243:         activeFilter = 'All Premieres';
244:         searchQuery = '';
245:         const searchEl = document.getElementById('premiereSearchInput');
246:         if (searchEl) searchEl.value = '';
247:         syncFilterPillsUi();
248:         renderPremieres();
249:       });
250:       return;
251:     }
252: 
253:     stack.innerHTML = list
254:       .map((film) => {
255:         const cd = formatCountdownParts(film.remainingSeconds);
256:         const btnClass = film.reminderActive ? 'btn-reminder-active' : 'btn-reminder-inactive';
257:         const btnContent = film.reminderActive
258:           ? `<span>&#10003; Reminder Enabled</span>`
259:           : `<span class="inline-flex items-center justify-center gap-2">
260:                <svg class="h-3.5 w-3.5 text-[#D4AF6A]" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
261:                  <path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/>
262:                  <path d="M10.3 21a1.94 1.94 0 0 0 3.4 0"/>
263:                </svg>
264:                <span>Notify Me</span>
265:              </span>`;
266: 
267:         return `
268:           <article class="luxury-card p-6 md:p-8" data-film-id="${film.id}">
269:             <div class="grid grid-cols-1 items-center gap-7 lg:grid-cols-12">
270:               <!-- Left Zone: Bespoke Vertical Art-Deco Poster Frame -->
271:               <div class="lg:col-span-3">
272:                 <button
273:                   type="button"
274:                   data-poster-open="${film.id}"
275:                   class="artdeco-poster block aspect-[3/4] w-full max-w-[230px] mx-auto lg:max-w-none text-left focus:outline-none"
276:                   aria-label="Open 4K Teaser Reel and Screening Notes for ${escapeHtml(film.title)}"
277:                 >
278:                   <div class="artdeco-poster-inner">
279:                     <div class="flex items-center justify-between">
280:                       <span class="text-[9.5px] font-semibold uppercase tracking-[0.26em] text-[#D4AF6A]">
281:                         PREMIERE
282:                       </span>
283:                       <span class="h-1.5 w-1.5 rounded-full bg-[#D4AF6A]/80"></span>
284:                     </div>
285: 
286:                     <div class="-mx-[0.9rem] min-h-0 flex-1 overflow-hidden bg-[#121011]">
287:                       <img
288:                         src="${escapeHtml(film.posterImage)}"
289:                         alt="${escapeHtml(film.title)} movie poster"
290:                         class="h-full w-full object-contain p-1"
291:                         loading="lazy"
292:                       />
293:                     </div>
294: 
295:                     <div class="border-t border-[rgba(212,175,106,0.22)] pt-2.5 text-center">
296:                       <p class="font-serif text-xs font-semibold uppercase tracking-[0.16em] text-[#F5F2EB]">
297:                         ${escapeHtml(film.title)}
298:                       </p>
299:                       <p class="mt-1 text-[8.5px] uppercase tracking-[0.22em] text-[#9E9895]">
300:                         THEATRON PRESENTATION
301:                       </p>
302:                     </div>
303:                   </div>
304:                 </button>
305:               </div>
306: 
307:               <!-- Center Zone: Film Metadata, Synopsis & Credits -->
308:               <div class="lg:col-span-5">
309:                 <div class="flex flex-wrap items-center gap-3">
310:                   <span class="rounded-full border border-[#8A2B3B] bg-[#3D141B] px-3 py-1 text-[10px] font-semibold uppercase tracking-[0.18em] text-[#D4AF6A]">
311:                     ${escapeHtml(film.genre)}
312:                   </span>
313:                   <span class="text-xs tracking-wide text-[#9E9895]">
314:                     ${escapeHtml(film.meta)}
315:                   </span>
316:                 </div>
317: 
318:                 <h2 class="mt-4 font-serif text-2xl font-semibold uppercase tracking-[0.14em] text-[#F5F2EB] sm:text-[26px]">
319:                   ${escapeHtml(film.title)}
320:                 </h2>
321: 
322:                 <p class="mt-3 line-clamp-2 text-sm leading-relaxed text-[#9E9895]">
323:                   ${escapeHtml(film.synopsis)}
324:                 </p>
325: 
326:                 <p class="mt-4 text-xs leading-relaxed text-[#9E9895]">
327:                   <span>Director:</span>
328:                   <span class="font-semibold text-[#D4AF6A]">${escapeHtml(film.director)}</span>
329:                   <span class="mx-1.5">&bull;</span>
330:                   <span>Cast:</span>
331:                   <span class="text-[#F5F2EB]">${escapeHtml(film.cast)}</span>
332:                 </p>
333: 
334:                 <button
335:                   type="button"
336:                   data-poster-open="${film.id}"
337:                   class="mt-4 inline-flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-[0.18em] text-[#D4AF6A] transition hover:text-[#F5F2EB]"
338:                 >
339:                   <span>4K Teaser &amp; Screening Notes</span>
340:                   <span aria-hidden="true">&rarr;</span>
341:                 </button>
342:               </div>
343: 
344:               <!-- Right Zone: Premiere Countdown Box & Priority Reminder Toggle -->
345:               <div class="lg:col-span-4">
346:                 <div class="rounded-xl border border-[rgba(212,175,106,0.18)] bg-[#131011] p-5">
347:                   <p class="eyebrow">PREMIERE COUNTDOWN</p>
348: 
349:                   <div class="mt-3.5 grid grid-cols-3 gap-2.5">
350:                     <div class="countdown-tile">
351:                       <span data-cd-days="${film.id}" class="block font-mono text-xl font-bold tracking-wider text-[#F5F2EB]">
352:                         ${cd.days}
353:                       </span>
354:                       <span class="mt-1 block text-[9px] font-semibold uppercase tracking-[0.2em] text-[#9E9895]">
355:                         DAYS
356:                       </span>
357:                     </div>
358:                     <div class="countdown-tile">
359:                       <span data-cd-hours="${film.id}" class="block font-mono text-xl font-bold tracking-wider text-[#F5F2EB]">
360:                         ${cd.hours}
361:                       </span>
362:                       <span class="mt-1 block text-[9px] font-semibold uppercase tracking-[0.2em] text-[#9E9895]">
363:                         HOURS
364:                       </span>
365:                     </div>
366:                     <div class="countdown-tile">
367:                       <span data-cd-secs="${film.id}" class="block font-mono text-xl font-bold tracking-wider text-[#D4AF6A]">
368:                         ${cd.secs}
369:                       </span>
370:                       <span class="mt-1 block text-[9px] font-semibold uppercase tracking-[0.2em] text-[#9E9895]">
371:                         SECS
372:                       </span>
373:                     </div>
374:                   </div>
375: 
376:                   <p class="mt-4 text-xs text-[#9E9895]">
377:                     Release: <span class="font-semibold text-[#F5F2EB]">${escapeHtml(film.releaseDate)}</span>
378:                   </p>
379: 
380:                   <button
381:                     type="button"
382:                     data-toggle-reminder="${film.id}"
383:                     class="mt-4 flex w-full items-center justify-center rounded-xl px-4 py-3 text-xs uppercase tracking-[0.15em] transition ${btnClass}"
384:                   >
385:                     ${btnContent}
386:                   </button>
387:                 </div>
388:               </div>
389:             </div>
390:           </article>
391:         `;
392:       })
393:       .join('');
394: 
395:     // Wire Poster / Screening Notes Modal Triggers
396:     stack.querySelectorAll('[data-poster-open]').forEach((btn) => {
397:       btn.addEventListener('click', () => {
398:         const id = btn.getAttribute('data-poster-open');
399:         const film = PREMIERES.find((p) => p.id === id);
400:         if (film) openTeaserModal(film);
401:       });
402:     });
403: 
404:     // Wire Reminder Toggle Buttons
405:     stack.querySelectorAll('[data-toggle-reminder]').forEach((btn) => {
406:       btn.addEventListener('click', () => {
407:         const id = btn.getAttribute('data-toggle-reminder');
408:         const film = PREMIERES.find((p) => p.id === id);
409:         if (!film) return;
410: 
411:         film.reminderActive = !film.reminderActive;
412:         updateReminderCounter();
413:         renderPremieres();
414: 
415:         if (film.reminderActive) {
416:           showToast('Priority Reminder Enabled', `${film.title} added to your VIP Gold alert queue.`);
417:         } else {
418:           showToast('Reminder Disabled', `Removed ${film.title} from priority opening-night alerts.`);
419:         }
420:       });
421:     });
422:   }
423: 
424:   // ------------------------------------------------------------------------
425:   // 4. Live 1-Second Countdown Ticker
426:   // ------------------------------------------------------------------------
427:   function startCountdownTicker() {
428:     setInterval(() => {
429:       PREMIERES.forEach((film) => {
430:         if (film.remainingSeconds > 0) {
431:           film.remainingSeconds -= 1;
432:         }
433:         const cd = formatCountdownParts(film.remainingSeconds);
434:         const daysEl = document.querySelector(`[data-cd-days="${film.id}"]`);
435:         const hoursEl = document.querySelector(`[data-cd-hours="${film.id}"]`);
436:         const secsEl = document.querySelector(`[data-cd-secs="${film.id}"]`);
437:         if (daysEl) daysEl.textContent = cd.days;
438:         if (hoursEl) hoursEl.textContent = cd.hours;
439:         if (secsEl) secsEl.textContent = cd.secs;
440:       });
441:     }, 1000);
442:   }
443: 
444:   // ------------------------------------------------------------------------
445:   // 5. Filter & Search Initialization
446:   // ------------------------------------------------------------------------
447:   function initFiltersAndSearch() {
448:     const pills = document.querySelectorAll('#genreFilterPills .filter-pill');
449:     pills.forEach((pill) => {
450:       pill.addEventListener('click', () => {
451:         activeFilter = pill.getAttribute('data-filter') || 'All Premieres';
452:         syncFilterPillsUi();
453:         renderPremieres();
454:       });
455:     });
456: 
457:     const statusPill = document.getElementById('reminderStatusPill');
458:     statusPill?.addEventListener('click', () => {
459:       activeFilter =
460:         activeFilter === 'Active Reminders Only' ? 'All Premieres' : 'Active Reminders Only';
461:       syncFilterPillsUi();
462:       renderPremieres();
463:     });
464: 
465:     const searchInput = document.getElementById('premiereSearchInput');
466:     searchInput?.addEventListener('input', (e) => {
467:       searchQuery = e.target.value || '';
468:       renderPremieres();
469:     });
470:   }
471: 
472:   // ------------------------------------------------------------------------
473:   // 6. Modals (4K Teaser Reel, Tickets, Profile, Admin)
474:   // ------------------------------------------------------------------------
475:   function openModal(eyebrow, title, bodyHtml) {
476:     const modal = document.getElementById('premiereModal');
477:     if (!modal) return;
478:     document.getElementById('premiereModalEyebrow').textContent = eyebrow;
479:     document.getElementById('premiereModalTitle').textContent = title;
480:     document.getElementById('premiereModalBody').innerHTML = bodyHtml;
481:     modal.classList.remove('hidden');
482:     modal.classList.add('flex');
483:   }
484: 
485:   function closeModal() {
486:     const modal = document.getElementById('premiereModal');
487:     if (!modal) return;
488:     modal.classList.add('hidden');
489:     modal.classList.remove('flex');
490:   }
491: 
492:   function openTeaserModal(film) {
493:     openModal(
494:       `4K TEASER REEL & SCREENING NOTES • ${film.genre.toUpperCase()}`,
495:       film.title,
496:       `
497:         <div class="space-y-4">
498:           <div class="relative overflow-hidden rounded-xl border border-[rgba(212,175,106,0.28)] bg-[#121011] p-6">
499:             <div class="flex flex-col items-center justify-center py-4 text-center">
500:               <img src="${film.posterImage}" alt="${escapeHtml(film.title)} poster" class="mx-auto h-auto max-h-[320px] w-auto max-w-[240px] rounded-lg" />
501:               <p class="mt-3 font-mono text-[11px] uppercase tracking-[0.2em] text-[#D4AF6A]">
502:                 4K DUAL-LASER MASTER PREVIEW • ${escapeHtml(film.formatSpec)}
503:               </p>
504:               <p class="mt-1 text-xs text-[#9E9895]">
505:                 Directed by ${escapeHtml(film.director)} &bull; Release ${escapeHtml(film.releaseDate)}
506:               </p>
507:             </div>
508:           </div>
509: 
510:           <p class="text-sm leading-relaxed text-[#F5F2EB]">
511:             ${escapeHtml(film.synopsis)}
512:           </p>
513: 
514:           <div class="rounded-xl border border-[rgba(212,175,106,0.16)] bg-[#121011] p-4 text-xs">
515:             <p class="eyebrow">CURATORIAL SCREENING NOTES</p>
516:             <p class="mt-1.5 leading-relaxed text-[#9E9895]">${escapeHtml(film.screeningNotes)}</p>
517:           </div>
518:         </div>
519:       `
520:     );
